def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    operations = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        t = int(parts[0])
        x_prime = int(parts[1])
        y = int(parts[2])
        x = x_prime / 100000  # fraction representation
        operations.append((t, x_prime, y))

    # earliest[j] = earliest time-step j bananas can be reached, or -1 if impossible
    earliest = [-1] * (m + 1)
    earliest[0] = float('inf')  # track this specially but we output for 1..m

    # reachable_at_step[i] = set of banana counts reachable at time-step i (after applying operation i)
    reachable = set()
    reachable.add(0)

    # After timestep 0 (initial), k=0 is reachable

    for step in range(1, n + 1):
        t, x_prime, y = operations[step - 1]
        x_i = x_prime  # working with numerator to avoid precision issues

        new_reachable = set()
        for k in reachable:
            if t == 1:
                # Type 1: apply k := ceil(k + x_i/100000) up to y times
                curr = k
                for a in range(y + 1):
                    if a == 0:
                        new_reachable.add(curr)
                    else:
                        # ceil(k + x_i/100000) = (k * 100000 + x_i + 100000 - 1) // 100000
                        next_k = (curr * 100000 + x_i + 100000 - 1) // 100000
                        curr = next_k
                        new_reachable.add(curr) if curr <= m else None
            else:
                # Type 2: apply k := ceil(k * x_i/100000) up to y times
                curr = k
                if curr == 0:
                    new_reachable.add(0)
                else:
                    for a in range(y + 1):
                        if a == 0:
                            new_reachable.add(curr)
                        else:
                            # ceil(curr * x_i/100000) = (curr * x_i + 100000 - 1) // 100000
                            next_k = (curr * x_i + 100000 - 1) // 100000
                            curr = next_k
                            new_reachable.add(curr) if curr <= m else None
        reachable = new_reachable

    # Now for each j, find the earliest time-step
    final_column = []

    # Update earliest reachability
    prev_step = 0
    for step in range(1, n + 1):
        t, x_prime, y = operations[step - 1]
        x_i = x_prime
        x_num = x_i
        new_reachable = set()
        for k in reachable:
            if t == 1:
                curr = k
                for a in range(y + 1):
                    if a == 0:
                        new_reachable.add(k)
                    else:
                        next_k = (curr * 100000 + x_num + 100000 - 1) // 100000
                        curr = next_k
                        if curr <= m:
                            new_reachable.add(curr)
            else:
                curr = k
                if curr == 0:
                    new_reachable.add(0)
                else:
                    for a in range(y + 1):
                        if a == 0:
                            new_reachable.add(k)
                        else:
                            next_k = (curr * x_num + 100000 - 1) // 100000
                            curr = next_k
                            if curr <= m:
                                new_reachable.add(curr)

        # Update answer for each reachable value
        for val in new_reachable:
            if earliest[val] == -1:
                earliest[val] = step

        reachable = new_reachable
        prev_step = step

    # Build result
    result = []
    for j in range(1, m + 1):
        result.append(earliest[j])

    return ' '.join(map(str, result)) + ' \n'

import math

def dist_sq(p1, p2):
    return (p1[0] - p2[0])**2 + (p1[1] - p2[1])**2 + (p1[2] - p2[2])**2

def dist(p1, p2):
    return math.sqrt(dist_sq(p1, p2))

def objective(point, planets):
    return max(dist(point, p) for p in planets)

def gradient(point, planets):
    max_dist = objective(point, planets)
    tight_points = []
    for i, p in enumerate(planets):
        if dist(point, p) >= max_dist - 1e-12:
            tight_points.append(i)

    if not tight_points:
        return [0.0, 0.0, 0.0], max_dist

    grad = [0.0, 0.0, 0.0]
    for idx in tight_points:
        diff = [point[i] - planets[idx][i] for i in range(3)]
        d = math.sqrt(sum(d2 for d2 in dist_sq(point, planets[idx])))
        if d > 1e-12:
            for i in range(3):
                grad[i] += diff[i] / d

    return grad, max_dist

