    elif n == 3:
        p0, p1, p2 = planets
        a = dist_sq(p0, p1)
        b = dist_sq(p0, p2)
        c = dist_sq(p1, p2)

        # Circumcenter of 3 points (triangle in 3D is actually 3D, need SPHERE)
        # For 3D min enclosing sphere of 3 points, use Wolfe's method
        # Actually just optimize
        return optimize(planets)
    else:
