def optimize(planets):
    centroid = tuple(sum(p[i] for p in planets) / len(planets) for i in range(3))
    best_point = centroid
    best_val = objective(best_point, planets)

    learning_rate = 0.5

    for iteration in range(50000):
        grad, current_val = gradient(best_point, planets)

        norm_grad_sq = grad[0]**2 + grad[1]**2 + grad[2]**2
        if norm_grad_sq < 1e-16:
            break

        direction = [best_point[i] - grad[i] * learning_rate for i in range(3)]

        if objective(direction, planets) < best_val:
            best_val = objective(direction, planets)
            best_point = tuple(direction)
        else:
            learning_rate *= 0.8

        if learning_rate < 1e-8:
            break

    return f"{best_point[0]:.11f} {best_point[1]:.11f} {best_point[2]:.11f}\n"

