    a = list(map(int, input_data[1].split()))

    def compute_grundy(k, max_val):
        memo = {}

        def grundy(n):
            if n == 0:
                return 0
            if n in memo:
                return memo[n]

            moves = set()

            # Option 1: Remove 1 cow -> state becomes n-1
            moves.add(grundy(n - 1))

            # Option 2: If n is even, n = 2 * x, replace with k piles of x cows
            if n % 2 == 0:
                x = n // 2
                # k piles of size x gives XOR sum of k copies of grundy(x)
                g = grundy(x)
                if k % 2 == 1:
                    # k is odd: XOR sum is g(x)
                    moves.add(g)
                else:
                    # k is even: XOR sum is 0
                    moves.add(0)

            # Compute MEX
            mex = 0
            while mex in moves:
                mex += 1

            memo[n] = mex
            return memo[n]

        return grundy

    # Compute grundy numbers for all values up to max(ai)
    max_a = max(a)
    if max_a == 0:
        xor_sum = 0
    else:
        grundy_fn = compute_grundy(k, max_a)
        xor_sum = 0
        for pile in a:
            xor_sum ^= grundy_fn(pile)

    if xor_sum > 0:
        return "Kevin\n"
    else:
        return "Nicky\n"

