                        parent[v] = u
                        tree_adj[u].append(v)
                        tree_adj[v].append(u)
                        dfs_tree(v)

            dfs_tree(odd_nodes[0])

            # Pair adjacent odd nodes in the component
            odd_set = set(odd_nodes)
            remaining = list(odd_nodes)
            path_idx = 0

            while len(remaining) > 1:
                # Find a path between two remaining odd nodes
                u, v = remaining[0], remaining[1]

                # BFS to find path
                q = [(u, [u])]
                visited_bfs = {u}
                found = False
                path_between = []

                while q and not found:
                    curr, p = q.pop(0)
                    if curr == v:
                        path_between = p
                        found = True
                        break
                    for neighbor in adj[curr]:
