def solution(input_string):
    if not input_string.strip():
        return ''

    lines = input_string.strip().split('\n')
    n, m = map(int, lines[0].split())

    edges = []
    for i in range(m):
        parts = lines[i+1].split()
        a, b, e = int(parts[0]), int(parts[1]), int(parts[2])
        edges.append((a-1, b-1, e, i))  # 0-indexed nodes

    if m == n - 1:
        return ''

    # Sort edges by weight for Kruskal's algorithm
    sorted_edges = sorted(edges, key=lambda x: x[2])

    # Kruskal's algorithm to build MST
    parent = list(range(n))
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py
            return True
        return False

    mst_set = set()
    mst_adj = [[] for _ in range(n)]

    for a, b, e, idx in sorted_edges:
        if union(a, b):
            mst_set.add((min(a, b), max(a, b)))
            mst_adj[a].append((b, e))
            mst_adj[b].append((a, e))

    # Binary lifting for LCA and path maximum queries
    LOG = 20
    depth = [0] * n
    up = [[-1] * LOG for _ in range(n)]
    max_edge = [[0] * LOG for _ in range(n)]

    # Iterative DFS to compute depths and binary lifting tables
    visited = [False] * n
    stack = [(0, -1, 0)]
    visited[0] = True

    while stack:
        u, p, w = stack.pop()

        depth[u] = depth[p] + 1 if p != -1 else 0
        up[u][0] = p
        max_edge[u][0] = w

        for i in range(1, LOG):
            if up[u][i-1] != -1:
                up[u][i] = up[up[u][i-1]][i-1]
                max_edge[u][i] = max(max_edge[u][i-1], max_edge[up[u][i-1]][i-1])
            else:
                up[u][i] = -1
                max_edge[u][i] = max_edge[u][i-1]

        for v, w_child in mst_adj[u]:
            if v != p:
                stack.append((v, u, w_child))

    def query_max_on_path(u, v):
        """Returns the maximum edge weight on the path between u and v in the MST"""
        ans = 0
        if depth[u] < depth[v]:
            u, v = v, u

        # Lift u to the same depth as v
        for i in range(LOG-1, -1, -1):
            if depth[u] - (1 << i) >= depth[v]:
                ans = max(ans, max_edge[u][i])
                u = up[u][i]

        if u == v:
            return ans

        # Lift both until just below LCA
        for i in range(LOG-1, -1, -1):
            if up[u][i] != up[v][i]:
                ans = max(ans, max_edge[u][i])
                ans = max(ans, max_edge[v][i])
                u = up[u][i]
                v = up[v][i]

        # Now u and v are children of LCA
        ans = max(ans, max_edge[u][0])
        ans = max(ans, max_edge[v][0])
        return ans

    # Process all non-MST edges
    results = []
    for a, b, e, idx in edges:
        if (min(a, b), max(a, b)) not in mst_set:
            results.append(str(query_max_on_path(a, b)))

    return '\n'.join(results)

