    for i in range(2, n + 1):
        log_table[i] = log_table[i >> 1] + 1

    max_log = log_table[n]

    # Build sparse tables for range max on v and min on c
    st_max_v = [[0] * n for _ in range(max_log + 1)]
    st_min_c = [[0] * n for _ in range(max_log + 1)]

    for i in range(n):
        st_max_v[0][i] = v[i]
        st_min_c[0][i] = c[i]

    for j in range(1, max_log + 1):
        prev_len = 1 << (j - 1)
        for i in range(n - prev_len + 1):
            st_max_v[j][i] = max(st_max_v[j-1][i], st_max_v[j-1][i + prev_len])
            st_min_c[j][i] = min(st_min_c[j-1][i], st_min_c[j-1][i + prev_len])

    def query_max(l, r):
        length = r - l + 1
        j = log_table[length]
        return max(st_max_v[j][l], st_max_v[j][r - (1 << j) + 1])

    def query_min(l, r):
        length = r - l + 1
        j = log_table[length]
        return min(st_min_c[j][l], st_min_c[j][r - (1 << j) + 1])

    # Compute optimal potential for each starting position
    best_potential = [0] * n
    for start in range(n):
