    # Use combinatorial formula: E = sum_{i=0}^{n-k} a[i] * C(n-i-1, k-1) / C(n, k)
    def comb(n_val, k_val):
        if k_val < 0 or k_val > n_val:
            return 0
        if k_val == 0 or k_val == n_val:
