def solution(input_str):
    lines = input_str.strip().split()
    m = int(lines[0])
    n = int(lines[1])

    # Parse the n integers starting from position 2
    a = []
    for i in range(n):
        a.append(int(lines[2 + i]))

    # Create a set for O(1) lookups
    s = set(a)

    if n == 1:
        # Single element is always an AP
        return f"{a[0]} 0\n"

    # Sort the array to examine consecutive differences
    s_sorted = sorted(a)

    # Collect candidate differences
    candidates = set()
    for i in range(n - 1):
        candidates.add(s_sorted[i + 1] - s_sorted[i])

    # Test each candidate difference
    for d in candidates:
        # For each possible starting element in the array
        for x in a:
            # Check if AP with (x, d) generates all elements
            valid = True
            for j in range(n):
                if (x + j * d) % m not in s:
                    valid = False
                    break

            if valid:
                return f"{x} {d}\n"

    # Also check complement differences (for wrap-around cases)
    for d in candidates:
        if d == m - d:
            continue
        # Test d = m - gap
        for x in a:
            valid = True
            for j in range(n):
                if (x + j * d) % m not in s:
                    valid = False
                    break

            if valid:
                return f"{x} {d}\n"

    return "-1\n"

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    A = [tuple(map(int, line.split())) for line in lines[1:n+1]]
    B = [tuple(map(int, line.split())) for line in lines[n+1:]]

    # Map B's rows to their original positions in A
    b_to_a = {}
    for i in range(n):
        for j in range(n):
            if A[j] == B[i]:
                b_to_a[i] = j
                break
        if i not in b_to_a:
            return "-1"

    target_state = tuple(b_to_a.values())

    from collections import deque

    initial_state = tuple(range(n))
    queue = deque([(initial_state, [])])
    visited = {initial_state}
    max_depth = 5000

    while queue:
        state, path = queue.popleft()

        if state == target_state:
            result = ["\n", " ".join(map(str, path))]
            return "\n".join(result)

        if len(path) >= max_depth:
            continue

        for col in range(m):
            # Compute new row ordering for given state after stable sort by column
            col_values = []
            for i in range(n):
                val = A[state[i]][col]
                col_values.append((val, state[i]))
            col_values.sort()
            new_state = [item[1] for item in col_values]
            new_state = tuple(new_state)

            if new_state not in visited:
                visited.add(new_state)
                queue.append((new_state, path + [col + 1]))

    return "-1"

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    if n == 1:
        MOD = 10**9 + 7
        return str(a[0] % MOD)

    MOD = 10**9 + 7

    # Compute binomial coefficients C(n-1, i) mod MOD
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def binomial(n, k):
        if k < 0 or k > n:
            return 0
        if k == 0 or k == n:
            return 1
        if k > n // 2:
            k = n - k
        numerator = 1
        denominator = 1
        for i in range(k):
            numerator = (numerator * (n - i)) % MOD
            denominator = (denominator * (i + 1)) % MOD
        return (numerator * pow(denominator, MOD - 2, MOD)) % MOD

    # Compute final result
    result = 0
    for i in range(n):
        coef = binomial(n - 1, i)
        term = (coef * a[i]) % MOD
        # Apply alternating signs
        if i % 2 == 1:
            result = (result - term + MOD) % MOD
        else:
            result = (result + term) % MOD

    return str(result)

