def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    q = int(lines[0])
    results = []
    idx = 1

    for _ in range(q):
        if idx >= len(lines):
            break
        a, b = map(int, lines[idx].split())
        s = lines[idx + 1]
        idx += 2

        # Find all segments of consecutive '.' characters
        segments = []
        cnt = 0
        for c in s:
            if c == '.':
                cnt += 1
            else:
                if cnt > 0:
                    segments.append(cnt)
                    cnt = 0
        if cnt > 0:
            segments.append(cnt)

        # Check if Alice can make any valid move
        has_move = False
        immediate_win = False
        strategy_win = False

        for l in segments:
            if l >= a:
                has_move = True
            # Check if Alice can play on this segment such that all remaining 
            # parts are less than b, meaning Bob has no moves
            if l >= a and (l - a + 1) // 2 < b:
                immediate_win = True
            # If there's a very large segment, Alice has advantage
            if l >= a + 2 * b - 1:
                strategy_win = True

        if not has_move:
            results.append("NO")
        elif immediate_win or strategy_win:
            results.append("YES")
        else:
            results.append("NO")

    return '\n'.join(results)


