def solution(input_str):
    lines = input_str.strip().split('\n')
    n, a, b = map(int, lines[0].split())
    p = list(map(int, lines[1].split()))

    # Map value to index for fast lookup
    val_to_idx = {v: i for i, v in enumerate(p)}

    # For each number, find its partner indices in A and B
    a_partner = [val_to_idx.get(a - p[i], -1) for i in range(n)]  # partner in set A
    b_partner = [val_to_idx.get(b - p[i], -1) for i in range(n)]  # partner in set B

    assignment = [-1] * n
    visited = set()

    for i in range(n):
        if i in visited:
            continue

        # Build connected component using both A and B partition edges
        component = []
        stack = [i]
        while stack:
            curr = stack.pop()
            if curr in visited:
                continue
            visited.add(curr)
            component.append(curr)

            # Add A-partner if exists
            partner_a = a_partner[curr]
            if partner_a != -1 and partner_a not in visited:
                stack.append(partner_a)

            # Add B-partner if exists  
            partner_b = b_partner[curr]
            if partner_b != -1 and partner_b not in visited:
                stack.append(partner_b)

        # Check if component can be validly assigned to set A (0)
        possible_0 = True
        for node in component:
            if a_partner[node] != -1 and a_partner[node] not in component:
                possible_0 = False
                break

        # Check if component can be validly assigned to set B (1)
        possible_1 = True
        for node in component:
            if b_partner[node] != -1 and b_partner[node] not in component:
                possible_1 = False
                break

        # If neither assignment is possible, the solution is impossible
        if not possible_0 and not possible_1:
            return "NO"

        # Try to assign to set 0 first if possible, otherwise set 1
        assigned_to = None
        if possible_0:
            assigned_to = 0
        elif possible_1:
            assigned_to = 1

        if assigned_to is None:
            return "NO"

        for node in component:
            assignment[node] = assigned_to

    # Format output
    result = []
    for i in range(n):
        if assignment[i] == 0:
            result.append('0')
        else:
            result.append('1')

    return "YES\n" + " ".join(result)

