def solution(input_str):
    n, p, l, r = map(int, input_str.strip().split())

    # dp[j] = number of valid queues with balance of j 50-yuan notes
    # Initially we have 0 notes
    dp = [0] * (n + 2)
    dp[0] = 1

    for _ in range(n):
        new_dp = [0] * (n + 2)
        for j in range(n + 2):
            if dp[j] == 0:
                continue

            count = dp[j] % p

            # Type A: +1 balance
            if j + 1 <= n + 1:
                new_dp[j + 1] = (new_dp[j + 1] + count) % p

            # Type B: -1 balance (only if current balance > 0)
            if j > 0:
                new_dp[j - 1] = (new_dp[j - 1] + count) % p
            # Note: if j == 0, type B is invalid and contributes nothing

            # Type C: 0 balance (implicitly handled by not modifying new_dp[j])
            new_dp[j] = (new_dp[j] + count) % p

        dp = new_dp

    # Sum up valid queues ending with balance in [l, r]
    ans = 0
    for j in range(l, r + 1):
        if j <= n + 1:
            ans = (ans + dp[j]) % p

    return str(ans)

