def solution(X: str):
    MOD = 10**9 + 7

    n = len(X)
    X_digits = [int(c) for c in X]

    # Digit DP: position, tight constrained, count < d, count >= d
    @lru_cache(None)
    def dp(pos, tight, less_count, ge_count):
        if pos == n:
            return 1

        limit = X_digits[pos] if tight else 9
        total = 0

        for digit in range(limit + 1):
            new_tight = tight and (digit == limit)
            new_less = less_count + (digit < d) for d in range(10)
            total = (total + dp(pos + 1, new_tight, new_less, ge_count)) % MOD

        return total

def count_ways(n, fibs):
    if n == 0:
        return 1
    # Find the largest Fibonacci number <= n
    i = bisect_right(fibs, n) - 1
    if i < 1:
        return 0
    # Either use fibs[i] or not
    return count_ways(n - fibs[i], fibs[:i]) + count_ways(n, fibs[:i-1])

