                for dr, dc in orientations[i]:
                    for pr, pc in [(start_r, start_c)]:
                        # Place T-piece
                        if is_valid(pr + dr, pc + dc, orientations[i]):
                            letter_idx = 0 if count == 0 else None
                            letter = chr(ord('A') + count - 1 if count > 0 else 0)
                            for dr2, dc2 in orientations[i]:
                                if 0 <= pr + dr2 < n and 0 <= pc + dc2 < m:
                                    if grid[pr + dr2][pc + dc2] == '.':
                                        grid[pr + dr2][pc + dc2] = chr(ord('A') + current_len)

                            current_len += 1
                            solve_grid(i + 1, current_len)

                            # backtrack
                            for dr2, dc2 in orientations[i]:
                                if 0 <= pr + dr2 < n and 0 <= pc + dc2 < m:
                                    grid[pr + dr2][pc + dc2] = '.'
                            current_len -= 1

    # Let me write cleaner code
    ans_grid = [['.' for _ in range(m)] for _ in range(n)]

    orientations_list = [
        [(0,0), (0,1), (0,2), (1,1), (2,1)],
        [(0,2), (1,1), (1,2), (1,3), (2,2)],
        [(0,1), (1,1), (2,1), (2,0), (2,2)],
        [(0,0), (1,1), (1,2), (2,0), (2,1)],
    ]

    best_ans = []
    best_grid_res = []
    max_placed = 0

    def try_place(r, c, shape, letter_idx, current_grid):
        nonlocal max_placed, best_ans, best_grid_res

        if r < 0 or c < 0 or r >= n or c >= m:
            return

        # Try to place this shape at (r, c)
        placed = True
        for dr, dc in shape:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < n and 0 <= nc < m):
                placed = False
                break
            if current_grid[nr][nc] != '.':
                placed = False
                break

        if placed:
            # Place the shape
            temp_grid = [row[:] for row in current_grid]
            for dr, dc in shape:
                nr, nc = r + dr, c + dc
                temp_grid[nr][nc] = chr(ord('A') + letter_idx)

            # Try backtracking to see if more can be placed
            count = 0
            for x in range(n):
                for y in range(m):
                    if temp_grid[x][y] != '.':
                        count += 1

            if count > max_placed:
                max_placed = count
                best_ans = [chr(ord('A') + i) for i in range(count)]
                best_grid_res = temp_grid

            # Continue placement
            for i in range(n * m):
                if temp_grid[i // m][i % m] == '.':
                    nr, nc = i // m, i % m
                    # Try placing from this cell
                    for j, shape in enumerate(orientations_list):
                        if try_place_placed(nr, nc, shape, count, temp_grid):
                            count += 1
                else:
                    break

    def try_place_placed(r, c, shape, letter_idx, current_grid):
        for dr, dc in shape:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < n and 0 <= nc < m) or current_grid[nr][nc] != '.':
                return False

        placed_grid = [row[:] for row in current_grid]
        for (dr, dc), char in zip(shape, [chr(ord('A') + letter_idx)] * len(shape)):
            nr, nc = r + dr, c + dc
            placed_grid[nr][nc] = char

        count = sum(1 for x in range(n) for y in range(m) if placed_grid[x][y] != '.')

        if count > max_placed:
            max_placed = count

    # Backtrack function
    def backtrack(grid_curr, placed_count):
        nonlocal max_placed, best_grid_res

        if placed_count > max_placed:
            max_placed = placed_count
            best_grid_res = [row[:] for row in grid_curr]

        # Find first empty cell
        start_find = placed_count * 3  # heuristic

        for i in range(start_find, n * m):
            r, c = i // m, i % m
            if grid_curr[r][c] != '.':
                continue

            # Try each orientation at this cell
            for shape in orientations_list:
                # Check if can place
                can_place = True
                for dr, dc in shape:
                    nr, nc = r + dr, c + dc
                    if not (0 <= nr < n and 0 <= nc < m) or grid_curr[nr][nc] != '.':
                        can_place = False
                        break

                if can_place:
                    # Place with current letter
                    new_letter_idx = placed_count
                    new_grid = [row[:] for row in grid_curr]
                    for dr, dc in shape:
                        nr, nc = r + dr, c + dc
                        new_grid[nr][nc] = chr(ord('A') + new_letter_idx)

                    backtrack(new_grid, placed_count + 1)

                    # Try to backtrack (don't need to restore grid since we create new)

    backtrack([['.' for _ in range(m)] for _ in range(n)], 0)

    # Convert best solution
    result_grid = [row[:] for row in best_grid_res]

    # Format output
    output_lines = [str(max_placed)]
    for row in result_grid:
        output_lines.append(''.join(row))

    return '\n'.join(output_lines) + '\n'


