from collections import deque

def solution(input_str):
    n = int(input_str.strip())

    if n == 0:
        return "0\n"

    # dist[x] = minimum operations to reduce x to 0
    dist = {n: 0}
    queue = deque([n])

    while queue:
        current = queue.popleft()

        if current == 0:
            return str(dist[current]) + '\n'

        # Extract unique digits in current number
        temp = current
        digits = set()
        while temp > 0:
            digits.add(temp % 10)
            temp //= 10

        for d in digits:
            next_val = current - d
            if next_val not in dist:
                dist[next_val] = dist[current] + 1
                queue.append(next_val)

    return str(dist[0]) + '\n'
